from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/get_user', methods=['GET'])
def get_user():
    user_id = request.args.get('user_id')

    user = {
        'id': user_id,
        'name': 'John Doe',
        'email': 'johndoe@example.com'
    }

    return jsonify(user)

